function [hd] = ring_rate(pump, h, tsd, fscale, h_max)
%RING_RATE  The ring's momentum rate [N m]: the pump's torque less the viscous loss h/t_sd (scaled by the unit's friction factor),
%   none that grows the momentum beyond the capacity.
%   pump: real[1] (passed a plain number)
%   h: real[1] (passed a plain number)
%   tsd: real[1] (passed a plain number)
%   fscale: real[1] (passed a plain number)
%   h_max: real[1] (passed a plain number)
%   returns hd: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    hd = 0;
    hd = asils.models.wheelspeed.momentum_limited((pump - ((h / tsd) * fscale)), h, h_max, 0);
end
